#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int n;
        cin >> n;
        string S, P;
        cin >> S >> P;

        long long diff0 = 0, diff1 = 0;
        int cur0 = 0, cur1 = 1;   // 当前目标位：假设首位为0或1

        for (int i = 0; i < n; ++i) {
            // 比较原始序列与两种目标序列
            if (S[i] - '0' != cur0) ++diff0;
            if (S[i] - '0' != cur1) ++diff1;

            // 还未到末尾，根据 P[i] 更新下一位的目标值
            if (i < n - 1) {
                int v = P[i] - '0';
                cur0 ^= v;
                cur1 ^= v;
            }
        }

        cout << min(diff0, diff1) << "\n";
    }
    return 0;
}
